################################################################################
# XGBoost with Fixed Hyperparameters - Full Cohort - Consolidated 43 Features
# Purpose: Production-ready model optimized for generalization
# NO FILTERING - uses all available cultures
# Uses NATIVE NA HANDLING (no imputation)
#
# CORE MODEL SCRIPT ONLY: data prep, train/test split, CV-based calibration,
# final model training, Platt calibration, and core performance metrics/CSVs.
# All figures, subgroup/missingness/cofactor/PCA/gram/specialty tables, and the
# EV comparison are generated by Do_XGBoost_FullCohort_FiguresAndTables.r, which
# reloads the saved model + calibration below and must be run after this script.
################################################################################

library(data.table)
library(xgboost)
library(pROC)
library(PRROC)
library(writexl)

set.seed(42)

# Create output folders
csv_dir <- "Output Files/CSVs/XGBoost/FullCohort"
model_dir <- "Models/XGBoost/FullCohort"
results_dir <- "Output Files/Publication_Tables_Figures/Metrics"
excel_dir <- "Output Files/Publication_Tables_Figures/Per_Model_Summaries"
dir.create(csv_dir, showWarnings = FALSE, recursive = TRUE)
dir.create(model_dir, showWarnings = FALSE, recursive = TRUE)
dir.create(results_dir, showWarnings = FALSE, recursive = TRUE)
dir.create(excel_dir, showWarnings = FALSE, recursive = TRUE)

bc_data <- fread("Output Files/CSVs/blood_cultures_with_other_micro.csv",
                 colClasses = c(ClusterID = "character"))

bc_data <- bc_data[CultivabilityCategory %in% c("Gram-positive", "Gram-negative", "Polymicrobial",
                                                  "Fungi", "Anaerobes", "Other",
                                                  "Culture-negative", "Contaminant - single", "Contaminant - recurrent",
                                                  "Polymicrobial - contaminant")]

bc_data[, Outcome := fifelse(CultivabilityCategory %in% c("Gram-positive", "Gram-negative", "Polymicrobial",
                                                            "Fungi", "Anaerobes", "Other"), 1L, 0L)]

# All pathogenic organisms included as positive outcomes (gram-classified, fungi, anaerobes)

# Feature engineering - CONSOLIDATED CATEGORICAL VARIABLES
bc_data[, Sex_num := fifelse(DEMOGRAPHICS_LinkedSex == "M", 1, 0)]
median_imd <- median(bc_data$SOCIAL_IMDPercentile, na.rm = TRUE)
bc_data[is.na(SOCIAL_IMDPercentile), SOCIAL_IMDPercentile := median_imd]

# Admission Type: 0=Other, 1=Emergency, 2=Elective (consolidated from 2 binary)
bc_data[, AdmissionType_num := fcase(
    AdmissionMethod == "Emergency", 1,
    AdmissionMethod == "Elective", 2,
    default = 0
  )]

# Culture Source Type: 0=Other, 1=Peripheral, 2=Central (consolidated from 2 binary)
bc_data[, SourceType_num := fcase(
  CultureSourceCategory == "Peripheral", 1,
  CultureSourceCategory %in% c("Central Line", "PICC", "Port/Portacath", "Arterial", "Femoral"), 2,
  default = 0
)]

# Infection Source: Keep 4 separate binary variables (respiratory was 1.06% gain)
for (col in c("Source_Urinary", "Source_Respiratory", "Source_Skin_Soft_Tissue", "Source_Other")) {
  bc_data[is.na(get(col)), (col) := 0]
}

bc_data[is.na(PositiveCulturesInPrior28Days), PositiveCulturesInPrior28Days := 0]

for (col in c("HasAntibiotics_Before", "BroadSpectrum_Before", "Ceph3rdGenPlus_Before", "Carbapenem_Before")) {
  bc_data[is.na(get(col)), (col) := 0]
}

for (col in c("Any_Prior_Other_Pos", "Prior_Urine_Pos")) {
  bc_data[is.na(get(col)), (col) := 0]
}

bc_data[, VS_AnyFever := fifelse(VS_AnyFever_38 == 1 & !is.na(VS_AnyFever_38), 1, 0)]
bc_data[, VS_AnyHypotension := fifelse(VS_AnyHypotension == 1 & !is.na(VS_AnyHypotension), 1, 0)]
bc_data[is.na(LOS_BeforeCulture_days), LOS_BeforeCulture_days := 0]

################################################################################
# SPLIT METHOD — swap between the two blocks below as needed
################################################################################

# --- OPTION A: Temporal split (active) ---
# Train: before 2024-01-01 | Hold-out test: 2024-01-01 onwards
bc_data[, CollectionDate := as.Date(CollectionDateTime)]
split_date <- as.Date("2024-01-01")
train_data <- bc_data[CollectionDate <  split_date]
test_data  <- bc_data[CollectionDate >= split_date]

# --- OPTION B: Random patient-level split (80/20) ---
# patient_outcomes     <- bc_data[, .(ever_positive = max(Outcome)), by = ClusterID]
# pos_patients         <- patient_outcomes[ever_positive == 1]$ClusterID
# neg_patients         <- patient_outcomes[ever_positive == 0]$ClusterID
# set.seed(42)
# train_pos_patients   <- sample(pos_patients, floor(0.8 * length(pos_patients)))
# train_neg_patients   <- sample(neg_patients, floor(0.8 * length(neg_patients)))
# train_data           <- bc_data[ClusterID %in% c(train_pos_patients, train_neg_patients)]
# test_data            <- bc_data[!ClusterID %in% c(train_pos_patients, train_neg_patients)]

################################################################################

# 5-FOLD CV SETUP FOR CALIBRATION (patient-level folds)
train_patient_outcomes <- train_data[, .(ever_positive = max(Outcome)), by = ClusterID]
train_pos_pats <- train_patient_outcomes[ever_positive == 1]$ClusterID
train_neg_pats <- train_patient_outcomes[ever_positive == 0]$ClusterID

set.seed(42)
train_pos_pats <- sample(train_pos_pats)
train_neg_pats <- sample(train_neg_pats)

k_folds <- 5
fold_assignments <- data.table(ClusterID = character(), Fold = integer())
for (i in 1:k_folds) {
  pos_fold <- train_pos_pats[seq(i, length(train_pos_pats), by = k_folds)]
  neg_fold <- train_neg_pats[seq(i, length(train_neg_pats), by = k_folds)]
  fold_assignments <- rbind(fold_assignments, data.table(ClusterID = c(pos_fold, neg_fold), Fold = i))
}

train_data <- merge(train_data, fold_assignments, by = "ClusterID", all.x = TRUE)

# NO IMPUTATION for continuous variables - XGBoost handles NA natively

# 32-feature set (removed: SOCIAL_IMDPercentile, BT_Closest_Urea, VS_AnyHypotension,
#   BT_Closest_HCT, BG_Closest_pCO2, Source_Urinary, Source_Skin_Soft_Tissue,
#   BT_Closest_Hb, Source_Other — zero/negligible AUC contribution)
feature_cols <- c(
  "AgeAtCulture", "Sex_num",
  "AdmissionType_num", "LOS_BeforeCulture_days",
  "SourceType_num",
  "PositiveCulturesInPrior28Days",
  "Source_Respiratory",
  "HasAntibiotics_Before", "BroadSpectrum_Before", "Ceph3rdGenPlus_Before", "Carbapenem_Before",
  "Any_Prior_Other_Pos", "Prior_Urine_Pos",
  "VS_Baseline_Temp", "VS_Baseline_SBP",
  "VS_Baseline_NEWS", "VS_AnyFever", "VS_Baseline_HR",
  "BT_Closest_CRP", "BT_Closest_WCC", "BT_Closest_Neut", "BT_Closest_Lymph",
  "BT_Closest_Alb", "BT_Closest_Plt", "BT_Closest_Creat", "BT_Closest_Bili",
  "BT_Closest_Na",
  "BT_Closest_Eosin", "BT_Closest_Mono", "BT_Closest_ALP",
  "BG_Closest_Lactate", "BG_Closest_pH"
)

train_matrix <- as.matrix(train_data[, ..feature_cols])
test_matrix <- as.matrix(test_data[, ..feature_cols])
train_label <- train_data$Outcome
test_label <- test_data$Outcome

scale_pos_weight <- sum(train_label == 0) / sum(train_label == 1)

params <- list(
  objective = "binary:logistic",
  eval_metric = "auc",
  max_depth = 8,
  eta = 0.0553,
  min_child_weight = 10,
  subsample = 0.9,
  colsample_bytree = 0.4,
  gamma = 3.971,
  lambda = 50,
  alpha = 0,
  scale_pos_weight = scale_pos_weight,
  nthread = min(4L, parallel::detectCores() - 1L)
)

################################################################################
# CV-BASED CALIBRATION: Get out-of-fold predictions for unbiased calibration
################################################################################

# Store out-of-fold predictions for calibration
train_data[, pred_oof := NA_real_]

cv_fold_aucs  <- numeric(k_folds)
cv_fold_auprcs <- numeric(k_folds)

for (fold in 1:k_folds) {
  # Split by fold
  train_fold <- train_data[Fold != fold]
  val_fold <- train_data[Fold == fold]

  train_fold_matrix <- as.matrix(train_fold[, ..feature_cols])
  val_fold_matrix <- as.matrix(val_fold[, ..feature_cols])

  dtrain_fold <- xgb.DMatrix(data = train_fold_matrix, label = train_fold$Outcome)
  dval_fold <- xgb.DMatrix(data = val_fold_matrix, label = val_fold$Outcome)

  # Train on this fold
  model_fold <- xgb.train(
    params = params,
    data = dtrain_fold,
    nrounds = 500,
    watchlist = list(train = dtrain_fold, val = dval_fold),
    early_stopping_rounds = 50,
    verbose = 0
  )

  # Predict on held-out fold
  val_pred <- predict(model_fold, dval_fold)
  train_data[Fold == fold, pred_oof := val_pred]

  cv_fold_aucs[fold]  <- as.numeric(auc(roc(val_fold$Outcome, val_pred, quiet = TRUE)))
  cv_fold_auprcs[fold] <- pr.curve(
    scores.class0 = val_pred[val_fold$Outcome == 1],
    scores.class1 = val_pred[val_fold$Outcome == 0]
  )$auc.integral
}

# Now train final model on ALL training data for production use
# Rebuild matrices fresh to avoid stale DMatrix state after CV loop
train_matrix <- as.matrix(train_data[, ..feature_cols])
test_matrix  <- as.matrix(test_data[,  ..feature_cols])
train_label  <- train_data$Outcome
test_label   <- test_data$Outcome

dtrain <- xgb.DMatrix(data = train_matrix, label = train_label)
dtest  <- xgb.DMatrix(data = test_matrix,  label = test_label)
watchlist <- list(train = dtrain, test = dtest)

model <- xgb.train(
    params = params,
    data = dtrain,
    nrounds = 500,
    watchlist = watchlist,
    early_stopping_rounds = 50,
    verbose = 0
  )

  # Predictions (uncalibrated) — pass matrix directly to avoid DMatrix thread-pool state issues
test_pred_raw <- predict(model, newdata = test_matrix)
train_pred_raw <- train_data$pred_oof  # Use out-of-fold predictions!

################################################################################
# PLATT SCALING CALIBRATION (fitted on out-of-fold predictions)
################################################################################

# Fit Platt model on OUT-OF-FOLD predictions (unbiased!)
train_pred_logit <- qlogis(pmax(pmin(train_pred_raw, 0.999), 0.001))
platt_model <- glm(train_label ~ train_pred_logit, family = binomial)

# Apply to test predictions
test_pred_logit <- qlogis(pmax(pmin(test_pred_raw, 0.999), 0.001))
test_pred <- predict(platt_model, newdata = data.frame(train_pred_logit = test_pred_logit), type = "response")
train_pred <- predict(platt_model, newdata = data.frame(train_pred_logit = train_pred_logit), type = "response")

# Calibration metrics
brier_raw <- mean((test_pred_raw - test_label)^2)
brier_calibrated <- mean((test_pred - test_label)^2)

# Train ROC using out-of-fold predictions
test_roc <- roc(test_label, test_pred, quiet = TRUE)
train_roc <- roc(train_label, train_pred, quiet = TRUE)

  coords_opt <- coords(test_roc, "best", ret = c("threshold", "sensitivity", "specificity"))
  threshold <- coords_opt$threshold

  test_pred_class <- ifelse(test_pred >= threshold, 1, 0)
  TP <- sum(test_pred_class == 1 & test_label == 1)
  TN <- sum(test_pred_class == 0 & test_label == 0)
  FP <- sum(test_pred_class == 1 & test_label == 0)
  FN <- sum(test_pred_class == 0 & test_label == 1)

  sensitivity <- TP / (TP + FN)
  specificity <- TN / (TN + FP)
  ppv <- TP / (TP + FP)
  npv <- TN / (TN + FN)
accuracy <- (TP + TN) / (TP + TN + FP + FN)
f1 <- 2 * ppv * sensitivity / (ppv + sensitivity)

pr_obj <- pr.curve(scores.class0 = test_pred[test_label == 1],
                   scores.class1 = test_pred[test_label == 0],
                   curve = TRUE)

################################################################################
# DECISION CURVE ANALYSIS (net benefit / cost) — data only, plots in Figures script
################################################################################

dca_thresholds <- seq(0.01, 0.50, by = 0.01)
n_test <- length(test_label)
prevalence <- mean(test_label)

dca_results <- lapply(dca_thresholds, function(pt) {
  pred_pos <- test_pred >= pt
  tp <- sum(pred_pos & test_label == 1)
  fp <- sum(pred_pos & test_label == 0)
  fn <- sum(!pred_pos & test_label == 1)

  nb_model <- (tp / n_test) - (fp / n_test) * (pt / (1 - pt))
  nb_treat_all <- prevalence - (1 - prevalence) * (pt / (1 - pt))
  nb_treat_none <- 0

  cost_model <- (fp / n_test) * (pt / (1 - pt)) + (fn / n_test)
  cost_treat_all <- (1 - prevalence) * (pt / (1 - pt))
  cost_treat_none <- prevalence

  data.frame(Threshold = pt, NB_Model = nb_model, NB_TreatAll = nb_treat_all, NB_TreatNone = nb_treat_none,
             Cost_Model = cost_model, Cost_TreatAll = cost_treat_all, Cost_TreatNone = cost_treat_none)
})
dca_df <- do.call(rbind, dca_results)
fwrite(dca_df, file.path(csv_dir, "decision_curve_analysis.csv"))

# ── Comparator DCA: CRP, NEWS, Shapiro vs XGBoost on test set ────────────
# Each raw score logistic-calibrated to a probability before NB computed
# (same approach as bench_dca_ev in the EV section)

test_data[, shapiro_score :=
  as.integer(AgeAtCulture > 65) +
  fcase(
    !is.na(VS_Baseline_Temp) & VS_Baseline_Temp >= 39.4, 3L,
    !is.na(VS_Baseline_Temp) & VS_Baseline_Temp >= 38.3, 1L,
    default = 0L
  ) +
  fifelse(CultureSourceCategory %in%
            c("Central Line", "PICC", "Port/Portacath", "Arterial", "Femoral"), 2L, 0L) +
  fifelse(!is.na(VS_Baseline_SBP)  & VS_Baseline_SBP < 90,     1L, 0L) +
  fifelse(!is.na(BT_Closest_WCC)   & BT_Closest_WCC > 18,      1L, 0L) +
  fifelse(!is.na(BT_Closest_Plt)   & BT_Closest_Plt < 150,     1L, 0L) +
  fifelse(!is.na(BT_Closest_Creat) & BT_Closest_Creat > 176.8, 1L, 0L)
]

comp_nb <- function(outcome, raw_score, thresholds) {
  d <- data.frame(outcome = outcome, score = raw_score)
  d <- d[!is.na(d$score) & !is.na(d$outcome), ]
  fit <- glm(outcome ~ score, data = d, family = binomial)
  d$pred <- predict(fit, type = "response")
  n <- nrow(d)
  sapply(thresholds, function(pt) {
    pos <- d$pred >= pt
    tp  <- sum(pos & d$outcome == 1)
    fp  <- sum(pos & d$outcome == 0)
    (tp / n) - (fp / n) * (pt / (1 - pt))
  })
}

comp_thresh <- seq(0.01, 0.30, by = 0.01)
n_comp      <- length(test_label)
prev_comp   <- mean(test_label)

comp_dca_df <- data.frame(
  Threshold   = comp_thresh,
  NB_XGBoost  = sapply(comp_thresh, function(pt) {
    pos <- test_pred >= pt
    (sum(pos & test_label == 1) / n_comp) - (sum(pos & test_label == 0) / n_comp) * (pt / (1 - pt))
  }),
  NB_TreatAll  = sapply(comp_thresh, function(pt) prev_comp - (1 - prev_comp) * (pt / (1 - pt))),
  NB_TreatNone = 0,
  NB_CRP       = comp_nb(test_data$Outcome, test_data$BT_Closest_CRP,      comp_thresh),
  NB_NEWS      = comp_nb(test_data$Outcome, test_data$VS_Baseline_NEWS,     comp_thresh),
  NB_Shapiro   = comp_nb(test_data$Outcome, test_data$shapiro_score,        comp_thresh)
)

fwrite(comp_dca_df, file.path(csv_dir, "dca_comparators.csv"))

################################################################################
# SAVE MODEL, CALIBRATION, AND CORE OUTPUTS
################################################################################

# Save test predictions for use by the Figures/Tables script and NBC comparisons
fwrite(data.table(pred = test_pred, outcome = test_label),
       file.path(csv_dir, "test_predictions.csv"))

# Save model (JSON format for xgboost 3.x compatibility), Platt calibration model, and importance
xgb.save(model, file.path(model_dir, "xgb_fullcohort.json"))
saveRDS(coef(platt_model), file.path(model_dir, "xgb_fullcohort_platt_calibration.rds"))

importance <- xgb.importance(model = model)
importance[, Pct_Gain := round(100 * Gain, 2)]
fwrite(importance, file.path(csv_dir, "feature_importance.csv"))

# Save standardized model summary for comparison script
model_summary <- data.frame(
  Metric = c("AUROC", "AUPRC", "Sensitivity", "Specificity", "PPV", "NPV", "F1", "Train-Test Gap", "Brier_Raw", "Brier_Calibrated"),
  Value = c(round(auc(test_roc), 3), round(pr_obj$auc.integral, 3),
            round(sensitivity, 3), round(specificity, 3),
            round(ppv, 3), round(npv, 3), round(f1, 3),
            round(auc(train_roc) - auc(test_roc), 3),
            round(brier_raw, 4), round(brier_calibrated, 4))
)
fwrite(model_summary, file.path(csv_dir, "model_summary.csv"))

# Additional summaries
calib_summary <- data.frame(
  Metric = c("Brier_Raw", "Brier_Calibrated", "Brier_Improvement_Pct"),
  Value = c(brier_raw, brier_calibrated, 100 * (brier_raw - brier_calibrated) / brier_raw)
)
fwrite(calib_summary, file.path(csv_dir, "calibration_summary.csv"))

# Cohort summary (with date range for TRIPOD 5b)
cohort_summary <- data.frame(
  Metric = c("Total_Cultures", "Total_Patients", "Train_N", "Test_N", "Positive_Rate",
             "Data_Start_Date", "Data_End_Date"),
  Value = c(nrow(bc_data), uniqueN(bc_data$ClusterID), nrow(train_data), nrow(test_data),
            100 * mean(bc_data$Outcome),
            as.character(as.Date(min(bc_data$CollectionDateTime, na.rm = TRUE))),
            as.character(as.Date(max(bc_data$CollectionDateTime, na.rm = TRUE))))
)
fwrite(cohort_summary, file.path(csv_dir, "cohort_summary.csv"))

################################################################################
# TABLE 2 METRICS — saved for compilation script
################################################################################

set.seed(42)
n_boot <- 1000
boot_auprcs_test <- vapply(seq_len(n_boot), function(b) {
  idx <- sample(length(test_label), replace = TRUE)
  bp  <- test_pred[idx]; bl <- test_label[idx]
  if (sum(bl) > 0 && sum(bl) < length(bl))
    pr.curve(scores.class0 = bp[bl == 1], scores.class1 = bp[bl == 0])$auc.integral
  else NA_real_
}, numeric(1))

auroc_ci   <- ci.auc(test_roc)
auprc_ci   <- quantile(boot_auprcs_test, c(0.025, 0.975), na.rm = TRUE)

table2_metrics <- data.frame(
  Model                = "XGBoost",
  CV_AUROC_Median      = round(median(cv_fold_aucs), 3),
  CV_AUROC_Q1          = round(quantile(cv_fold_aucs, 0.25), 3),
  CV_AUROC_Q3          = round(quantile(cv_fold_aucs, 0.75), 3),
  CV_AUPRC_Median      = round(median(cv_fold_auprcs), 3),
  CV_AUPRC_Q1          = round(quantile(cv_fold_auprcs, 0.25), 3),
  CV_AUPRC_Q3          = round(quantile(cv_fold_auprcs, 0.75), 3),
  Test_AUROC           = round(as.numeric(auc(test_roc)), 3),
  Test_AUROC_CI_Lower  = round(auroc_ci[1], 3),
  Test_AUROC_CI_Upper  = round(auroc_ci[3], 3),
  Test_AUPRC           = round(pr_obj$auc.integral, 3),
  Test_AUPRC_CI_Lower  = round(auprc_ci[1], 3),
  Test_AUPRC_CI_Upper  = round(auprc_ci[2], 3),
  Test_Sensitivity     = round(sensitivity, 3),
  Test_Specificity     = round(specificity, 3),
  Test_PPV             = round(ppv, 3),
  Test_NPV             = round(npv, 3),
  Test_Brier           = round(brier_calibrated, 3)
)
fwrite(table2_metrics, file.path(results_dir, "table2_metrics_xgboost.csv"))

################################################################################
# SENSITIVITY-LOCKED THRESHOLD ANALYSIS (Youden, 95%, 98%)
################################################################################

calc_metrics_at_sensitivity <- function(label, thresh, test_pred, test_label) {
  pred_class <- ifelse(test_pred >= thresh, 1L, 0L)
  TP <- sum(pred_class == 1 & test_label == 1)
  TN <- sum(pred_class == 0 & test_label == 0)
  FP <- sum(pred_class == 1 & test_label == 0)
  FN <- sum(pred_class == 0 & test_label == 1)
  data.frame(
    Operating_Point = label,
    Threshold       = round(thresh, 4),
    Sensitivity     = round(TP / (TP + FN), 3),
    Specificity     = round(TN / (TN + FP), 3),
    PPV             = round(TP / (TP + FP), 3),
    NPV             = round(TN / (TN + FN), 3),
    FPR             = round(FP / (FP + TN), 3),
    N_Flagged       = TP + FP,
    N_Flagged_Pct   = round(100 * (TP + FP) / length(test_label), 1)
  )
}

find_threshold_at_sensitivity <- function(target_sens, test_roc) {
  roc_df <- data.frame(thresh = test_roc$thresholds,
                       sens   = test_roc$sensitivities,
                       spec   = test_roc$specificities)
  candidates <- roc_df[roc_df$sens >= target_sens, ]
  candidates$thresh[which.max(candidates$spec)]
}

sens_thresholds <- rbind(
  calc_metrics_at_sensitivity("Youden (optimal)", threshold, test_pred, test_label),
  calc_metrics_at_sensitivity("95% Sensitivity",  find_threshold_at_sensitivity(0.95, test_roc), test_pred, test_label),
  calc_metrics_at_sensitivity("98% Sensitivity",  find_threshold_at_sensitivity(0.98, test_roc), test_pred, test_label)
)

fwrite(sens_thresholds, file.path(csv_dir, "sensitivity_locked_thresholds.csv"))

# Save model summary as Excel (single write, all sheets)
write_xlsx(list(
  Model_Summary          = model_summary,
  Calibration_Summary    = calib_summary,
  Sensitivity_Thresholds = sens_thresholds
), file.path(excel_dir, "XGBoost_FullCohort_Summary.xlsx"))
